int get_data_block_for_inode(struct inode *inode, sector_t iblock,
                             struct buffer_head *bh, int create, int flag,
                             pgoff_t *next_pgofs) {
    int ret;
    struct address_space *mapping = inode->i_mapping;
    struct buffer_head *mapped_bh;

    mapped_bh = get_block_mapping(mapping, iblock, flag, next_pgofs, create);
    if (IS_ERR(mapped_bh)) {
        return PTR_ERR(mapped_bh);
    }

    if (!mapped_bh) {
        return -ENODATA;
    }

    *bh = *mapped_bh;
    brelse(mapped_bh);
    return 0;
}

int get_data_block(struct inode *inode, sector_t iblock, struct buffer_head *bh, int create, int flag, pgoff_t *next_pgofs) {
    struct address_space *mapping = inode->i_mapping;
    int ret;

    ret = block_map(mapping, iblock, flag, create, bh);
    if (ret < 0)
        return ret;

    if (next_pgofs)
        *next_pgofs = iblock + 1;

    return 0;
}

int retrieve_inode_block(struct inode *inode, sector_t iblock, struct buffer_head *bh, int create, int flag, pgoff_t *next_pgofs) {
    int ret;
    struct address_space *mapping = inode->i_mapping;
    struct page *page;

    page = read_mapping_page(mapping, iblock, NULL);
    if (IS_ERR(page)) {
        return PTR_ERR(page);
    }

    if (!page) {
        if (create) {
            page = alloc_page(GFP_NOFS);
            if (!page) {
                return -ENOMEM;
            }
            page_cache_ext_init(page);
        } else {
            return -ENOENT;
        }
    }

    bh->b_page = page;
    bh->b_offset = iblock * PAGE_SIZE;
    bh->b_size = PAGE_SIZE;

    *next_pgofs = iblock + 1;

    return 0;
}

int retrieve_inode_block(struct inode *inode, sector_t iblock, struct buffer_head *bh, int create, int flag, pgoff_t *next_pgofs) {
    struct address_space *mapping = inode->i_mapping;
    int ret;

    ret = block_map(mapping, iblock, create, flag, bh, next_pgofs);
    if (ret < 0)
        return ret;

    if (!bh)
        return -EIO;

    return 0;
}

int get_data_block(struct inode *inode, sector_t iblock, struct buffer_head *bh, int create, int flag, pgoff_t *next_pgofs) {
    int ret;
    struct address_space *mapping = inode->i_mapping;
    struct bvec bv;

    ret = block_map(mapping, iblock, &bv, create, flag);
    if (ret < 0)
        return ret;

    bh->b_bdev = inode->i_sb->s_bdev;
    bh->b_blocknr = ret;
    bh->b_size = inode->i_sb->s_blocksize;
    bh->b_state = 0;
    set_buffer_mapped(bh);

    if (next_pgofs)
        *next_pgofs = iblock + 1;

    return 0;
}
